import os


def walk(path, depth=0, max_depth=3):
    if depth > max_depth:
        return
    try:
        entries = sorted(os.listdir(path))
    except PermissionError:
        return
    for entry in entries:
        full = os.path.join(path, entry)
        if entry in (".codex", ".git", "__pycache__") or entry.startswith("."):
            continue
        if os.path.isdir(full):
            print(f"{'  ' * depth}[dir] {full}")
            walk(full, depth + 1, max_depth)
        else:
            print(f"{'  ' * depth}[file] {full} ({os.path.getsize(full)} bytes)")


walk(".")

